-- Spike schema. Production schema will be generated by drizzle-kit in P0.
-- Time columns are unix seconds (UTC) per AGENTS.md constraint 9.

CREATE TABLE `user` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `name` TEXT NOT NULL,
  `email` TEXT NOT NULL COLLATE NOCASE,
  `email_verified` INTEGER NOT NULL DEFAULT 0,
  `image` TEXT,
  `username` TEXT,
  `role` TEXT NOT NULL DEFAULT 'user',
  `status` TEXT NOT NULL DEFAULT 'active',
  `bio` TEXT,
  `avatar_key` TEXT,
  `timezone` TEXT,
  `last_seen_at` INTEGER,
  `deleted_at` INTEGER,
  `created_at` INTEGER NOT NULL,
  `updated_at` INTEGER NOT NULL,
  CONSTRAINT `user_email_unique` UNIQUE (`email`),
  CONSTRAINT `user_username_unique` UNIQUE (`username`),
  CONSTRAINT `user_role_check` CHECK (`role` IN ('user','moderator','admin')),
  CONSTRAINT `user_status_check` CHECK (`status` IN ('active','suspended','deleting','deleted'))
);

CREATE TABLE `session` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `expires_at` INTEGER NOT NULL,
  `token` TEXT NOT NULL,
  `ip_address` TEXT,
  `user_agent` TEXT,
  `user_id` TEXT NOT NULL,
  `created_at` INTEGER NOT NULL,
  `updated_at` INTEGER NOT NULL,
  CONSTRAINT `session_token_unique` UNIQUE (`token`),
  CONSTRAINT `session_user_fk` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
);
CREATE INDEX `session_user_id_idx` ON `session` (`user_id`);
CREATE INDEX `session_expires_at_idx` ON `session` (`expires_at`);

CREATE TABLE `account` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `account_id` TEXT NOT NULL,
  `provider_id` TEXT NOT NULL,
  `user_id` TEXT NOT NULL,
  `access_token` TEXT,
  `refresh_token` TEXT,
  `id_token` TEXT,
  `access_token_expires_at` INTEGER,
  `refresh_token_expires_at` INTEGER,
  `scope` TEXT,
  `password` TEXT,
  `created_at` INTEGER NOT NULL,
  `updated_at` INTEGER NOT NULL,
  CONSTRAINT `account_user_fk` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `account_provider_unique` UNIQUE (`provider_id`, `account_id`)
);
CREATE INDEX `account_user_id_idx` ON `account` (`user_id`);

CREATE TABLE `verification` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `identifier` TEXT NOT NULL,
  `value` TEXT NOT NULL,
  `expires_at` INTEGER NOT NULL,
  `created_at` INTEGER,
  `updated_at` INTEGER
);
CREATE INDEX `verification_identifier_idx` ON `verification` (`identifier`);

CREATE TABLE `rateLimit` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `key` TEXT NOT NULL,
  `count` INTEGER NOT NULL,
  `last_request` INTEGER NOT NULL,
  CONSTRAINT `rate_limit_key_unique` UNIQUE (`key`)
);

-- Forum tables (minimal; only what the spikes exercise).
CREATE TABLE `categories` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `slug` TEXT NOT NULL,
  `name` TEXT NOT NULL,
  `created_at` INTEGER NOT NULL,
  CONSTRAINT `categories_slug_unique` UNIQUE (`slug`)
);

CREATE TABLE `topics` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `category_id` TEXT NOT NULL,
  `author_id` TEXT NOT NULL,
  `first_post_id` TEXT,
  `status` TEXT NOT NULL DEFAULT 'published',
  `pin_level` INTEGER NOT NULL DEFAULT 0,
  `pin_order` INTEGER NOT NULL DEFAULT 0,
  `is_locked` INTEGER NOT NULL DEFAULT 0,
  `reply_count` INTEGER NOT NULL DEFAULT 0,
  `last_post_at` INTEGER NOT NULL,
  `version` INTEGER NOT NULL DEFAULT 1,
  `created_at` INTEGER NOT NULL,
  `updated_at` INTEGER NOT NULL,
  CONSTRAINT `topics_category_fk` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `topics_status_check` CHECK (`status` IN ('published','hidden','deleted','pending','rejected'))
);
CREATE INDEX `topics_list_idx` ON `topics` (`status`, `pin_level` DESC, `pin_order`, `last_post_at` DESC);

CREATE TABLE `posts` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `topic_id` TEXT NOT NULL,
  `author_id` TEXT NOT NULL,
  `floor` INTEGER NOT NULL,
  `is_first` INTEGER NOT NULL DEFAULT 0,
  `title` TEXT,
  `content_md` TEXT NOT NULL,
  `content_text` TEXT NOT NULL,
  `status` TEXT NOT NULL DEFAULT 'published',
  `version` INTEGER NOT NULL DEFAULT 1,
  `edit_count` INTEGER NOT NULL DEFAULT 0,
  `edited_at` INTEGER,
  `created_at` INTEGER NOT NULL,
  `updated_at` INTEGER NOT NULL,
  CONSTRAINT `posts_topic_fk` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `posts_topic_floor_unique` UNIQUE (`topic_id`, `floor`),
  CONSTRAINT `posts_status_check` CHECK (`status` IN ('published','hidden','deleted','pending','rejected'))
);
CREATE INDEX `posts_topic_idx` ON `posts` (`topic_id`, `status`, `floor`);
CREATE INDEX `posts_author_idx` ON `posts` (`author_id`, `created_at` DESC);

CREATE TABLE `post_revisions` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `topic_id` TEXT NOT NULL,
  `post_id` TEXT NOT NULL,
  `version` INTEGER NOT NULL,
  `title` TEXT,
  `content_md` TEXT NOT NULL,
  `action` TEXT NOT NULL,
  `editor_id` TEXT NOT NULL,
  `reason` TEXT,
  `created_at` INTEGER NOT NULL,
  CONSTRAINT `post_revisions_post_version_unique` UNIQUE (`post_id`, `version`),
  CONSTRAINT `post_revisions_action_check` CHECK (`action` IN ('edit','delete','restore'))
);
CREATE INDEX `post_revisions_post_idx` ON `post_revisions` (`post_id`, `version` DESC);

-- FTS5: post_uid is UNINDEXED; rowid stays an internal integer.
CREATE VIRTUAL TABLE `post_search` USING fts5(
  `post_uid` UNINDEXED,
  `topic_id` UNINDEXED,
  `title`,
  `tokens`,
  tokenize = 'unicode61 remove_diacritics 2'
);

-- Spike-only bookkeeping for reset/email waitUntil evidence.
CREATE TABLE `spike_outbox` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `kind` TEXT NOT NULL,
  `payload` TEXT NOT NULL,
  `created_at` INTEGER NOT NULL
);
